import { Box, SidePanel, Text } from '@wix/design-system';
import classNames from 'classnames';
import React from 'react';

import { PANEL_HEADER_ID } from './../consts.js';

import classes from './panel-header-scss.js';

type PanelHeaderProps = {
  title: React.ReactNode;
  subtitle?: React.ReactNode;
  className?: string;
};

export const PanelHeader: React.FC<PanelHeaderProps> = ({ title, subtitle, className }) => {
  return (
    <div data-drag-handler="true">
      <SidePanel.Header
        showDivider
        className={classNames(classes.header, className)}
        title={
          <Box>
            <Text id={PANEL_HEADER_ID} placement="auto" as="h2" size="medium" weight="bold">
              {title}
            </Text>
          </Box>
        }
        subtitle={subtitle}
      />
    </div>
  );
};
