import type { PmMarkConverter } from './../pm-converters/types.js';
import type { ColorDecoration } from './../ricos-schema/next-schema/index.js';
import { Decoration_Type } from './../ricos-schema/next-schema/index.js';
import { Mark_Type } from './../ricos-types/index.js';

export const textColorConverter: PmMarkConverter = {
  fromPm: {
    type: Mark_Type.COLOR_FOREGROUND,
    convert: mark => {
      const textColor = mark.attrs?.color;
      if (!textColor) {
        return [];
      }
      return [
        {
          type: Decoration_Type.COLOR,
          colorData: {
            foreground: textColor,
          },
        },
      ];
    },
  },
  toPm: {
    type: Decoration_Type.COLOR,
    convert: decoration => {
      const { colorData } = decoration as ColorDecoration;
      const textColor = colorData?.foreground;
      if (!textColor) {
        return undefined;
      }
      return {
        type: Mark_Type.COLOR_FOREGROUND,
        attrs: { color: textColor },
      };
    },
  },
};

