import type { FC } from 'react';
import React, { useContext, useEffect, useState } from 'react';

import { EditorContext, ModalServiceContext, RicosContext } from './../ricos-context/index.js';
import { useBiNext } from './../_shared/bi-context-provider/bi-context-provider.js';
import {
  handleColorAdded,
  handleColorDeleted,
  resolveThemeColorsPalette,
  useResolvedCustomColors,
} from './../_shared/color-manager-utils.js';
import { NewColorPicker } from './../ui-components/color-picker/new-color-picker/index.js';

import { TEXT_COLOR_MODAL_ID, TEXT_HIGHLIGHT_MODAL_ID } from './constants.js';
import type { TextColorPluginEditorConfig, TextHighlightPluginEditorConfig } from './types.js';

type TextColorPickerProps = {
  type: 'ricos-text-color' | 'ricos-text-highlight';
  config: TextColorPluginEditorConfig | TextHighlightPluginEditorConfig;
  referenceElement: HTMLDivElement | undefined;
};

const useCurrentColor = (type: 'ricos-text-color' | 'ricos-text-highlight'): string | undefined => {
  const { getPublicCommands, adapter } = useContext(EditorContext);
  const [color, setColor] = useState<string | undefined>(() =>
    getPublicCommands()?.getColor?.(type)
  );

  useEffect(() => {
    const updateColor = () => {
      setColor(getPublicCommands()?.getColor?.(type));
    };

    const { tiptapEditor } = adapter;

    tiptapEditor.on('transaction', updateColor);
    tiptapEditor.on('update', updateColor);
    tiptapEditor.on('selectionUpdate', updateColor);

    return () => {
      tiptapEditor.off('transaction', updateColor);
      tiptapEditor.off('update', updateColor);
      tiptapEditor.off('selectionUpdate', updateColor);
    };
  }, [adapter, getPublicCommands, type]);

  return color;
};

export const TextColorPicker: FC<TextColorPickerProps> = ({ type, config, referenceElement }) => {
  const { t, colorManager, theme } = useContext(RicosContext);
  const { getPublicCommands } = useContext(EditorContext);
  const { adapter } = useContext(EditorContext);
  const modalService = useContext(ModalServiceContext);

  const isTextHighlightModal = type === 'ricos-text-highlight';
  const modalId = isTextHighlightModal ? TEXT_HIGHLIGHT_MODAL_ID : TEXT_COLOR_MODAL_ID;
  const pluginId = isTextHighlightModal ? 'textHighlight' : 'textColor';

  const logBi = useBiNext({ modalId, pluginId });

  const currentColor = useCurrentColor(type);

  const themeColors = resolveThemeColorsPalette(
    theme,
    config.colorScheme ? Object.values(config.colorScheme).map(c => c.color) : []
  );

  const customColors = useResolvedCustomColors(colorManager, config.getUserColors);

  const closeModal = () => {
    modalService.closeModal(modalId);
  };

  const onColorSelected = (color: string | undefined) => {
    getPublicCommands()?.insertDecoration(type, { color });
  };

  const onColorAdded = (color: string) => {
    handleColorAdded(color, colorManager, config.onColorAdded);
    getPublicCommands()?.insertDecoration(type, { color });
  };

  const onColorDeleted = (color: string) => {
    handleColorDeleted(color, colorManager);
  };

  const onResetColor = () => {
    getPublicCommands()?.deleteDecoration(type);
  };

  const onPreview = (color: string | null) => {
    const previewCommand = isTextHighlightModal ? 'previewHighlight' : 'previewColor';
    adapter.tiptapEditor.chain()[previewCommand](color).run();
  };

  const onColorPreviewStart = (color: string | undefined) =>
    // @ts-ignore $TSFixMe
    onPreview(color);

  const onColorPreviewEnd = () => onPreview(null);

  return (
    <NewColorPicker
      title={
        isTextHighlightModal
          ? t('Color_Picker_TextHighlightButton_Header')
          : t('Color_Picker_TextColorButton_Header')
      }
      currentColor={currentColor}
      themeColors={themeColors}
      customColors={customColors}
      closeModal={closeModal}
      onColorSelected={onColorSelected}
      onColorAdded={onColorAdded}
      onColorDeleted={colorManager || !config.getUserColors ? onColorDeleted : undefined}
      onColorPreviewStart={onColorPreviewStart}
      onColorPreviewEnd={onColorPreviewEnd}
      onResetColor={onResetColor}
      referenceElement={referenceElement}
      logBi={logBi}
    />
  );
};
