import { Box } from '@wix/design-system';
import classNames from 'classnames';
import type { FC } from 'react';
import React, { useEffect, useRef, useState } from 'react';

import type { Gradient, GradientStop } from './../../../../../ricos-types/color-palette-types.js';
import { schemaGradientToCss } from './../../../../../_shared/schema-gradient-to-css.js';
import { resolveDocumentColorToCss } from './../../../../../_shared/theme-color-token.js';

import { roundPosition } from './gradient-picker-utils.js';
import classes from './gradient-picker-scss.js';

type ColorStopsProps = {
  value: Gradient;
  onChange: (gradient: Gradient) => void;
  onStopClick: (index: number) => void;
  canAddStop: boolean;
};

export const ColorStops: FC<ColorStopsProps> = ({ value, onChange, onStopClick, canAddStop }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const wasDraggingRef = useRef(false);

  const handleAddStopAtPosition = (event: React.MouseEvent<HTMLDivElement>) => {
    if (!canAddStop || wasDraggingRef.current) {
      wasDraggingRef.current = false;
      return;
    }

    const clickX = event.clientX;
    const containerRect = containerRef.current?.getBoundingClientRect();
    const containerX = containerRect?.left ?? 0;
    const clickXRelativeToContainer = clickX - containerX;
    const clickXRelativeToContainerPercentage =
      (clickXRelativeToContainer / (containerRect?.width ?? 1)) * 100;

    const newStops = [
      ...(value.stops ?? []),
      {
        color: value.stops?.[value.stops.length - 1]?.color,
        position: roundPosition(clickXRelativeToContainerPercentage / 100),
      },
    ].sort((a, b) => (a.position ?? 0) - (b.position ?? 0));

    onChange({
      ...value,
      stops: newStops,
    });
  };

  return (
    <Box paddingTop="SP3" paddingLeft="SP1" paddingRight="SP1">
      <div
        className={classes.stops}
        ref={containerRef}
        role="presentation"
        aria-label="Gradient stops bar. Click to add a stop or use the Add button."
        style={
          {
            '--gp-stops-gradient': schemaGradientToCss({
              type: 'LINEAR',
              stops: value.stops,
              angle: 90,
            }),
          } as React.CSSProperties
        }
        onClick={handleAddStopAtPosition}
      >
        {value.stops?.map((stop, index) => (
          <ColorStop
            key={index}
            stop={stop}
            onChange={newStop => {
              onChange({
                ...value,
                stops: value.stops?.map((s, i) => (i === index ? newStop : s)),
              });
            }}
            onStopClick={() => {
              onStopClick(index);
            }}
            containerRef={containerRef}
            wasDraggingRef={wasDraggingRef}
          />
        ))}
      </div>
    </Box>
  );
};

type ColorStopProps = {
  stop: GradientStop;
  onChange: (stop: GradientStop) => void;
  containerRef: React.RefObject<HTMLDivElement>;
  onStopClick: () => void;
  wasDraggingRef: React.MutableRefObject<boolean>;
};

const ColorStop: FC<ColorStopProps> = ({
  stop,
  onChange,
  containerRef,
  onStopClick,
  wasDraggingRef,
}) => {
  const [isDragging, setIsDragging] = useState(false);
  const draggedDuringMouseDownRef = useRef(false);
  const stopRef = useRef(stop);
  const onChangeRef = useRef(onChange);
  stopRef.current = stop;
  onChangeRef.current = onChange;

  const handleKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
    switch (event.key) {
      case 'ArrowLeft': {
        event.preventDefault();
        const currentPosition = (stop.position ?? 0) * 100;
        const newPositionLeft = Math.max(0, currentPosition - 1);
        onChange({ ...stop, position: roundPosition(newPositionLeft / 100) });
        break;
      }
      case 'ArrowRight': {
        event.preventDefault();
        const currentPosition = (stop.position ?? 0) * 100;
        const newPositionRight = Math.min(100, currentPosition + 1);
        onChange({ ...stop, position: roundPosition(newPositionRight / 100) });
        break;
      }
      case 'Enter': {
        event.preventDefault();
        onStopClick();
        break;
      }
      default:
        break;
    }
  };

  useEffect(() => {
    if (!isDragging) {
      return;
    }

    const handleMouseMove = (event: MouseEvent) => {
      if (containerRef.current) {
        draggedDuringMouseDownRef.current = true;
        const containerRect = containerRef.current.getBoundingClientRect();
        const x = event.clientX - containerRect.left;
        const centerX = Math.max(0, Math.min(100, (x / containerRect.width) * 100));
        onChangeRef.current({
          ...stopRef.current,
          position: roundPosition(centerX / 100),
        });
      }
    };

    const handleMouseUp = (event: MouseEvent) => {
      event.stopPropagation();
      if (draggedDuringMouseDownRef.current) {
        wasDraggingRef.current = true;
      }
      setIsDragging(false);
    };

    document.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('mouseup', handleMouseUp);

    return () => {
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseup', handleMouseUp);
    };
  }, [isDragging]);

  return (
    <div
      role="button"
      tabIndex={0}
      aria-live="polite"
      className={classNames(classes.stopContainer, {
        [classes.active]: isDragging,
      })}
      style={{ left: `${(stop.position ?? 0) * 100}%` }}
      onClick={event => {
        event.stopPropagation();
        if (!draggedDuringMouseDownRef.current) {
          onStopClick();
        }
      }}
      onMouseDown={event => {
        event.stopPropagation();
        setIsDragging(true);
        draggedDuringMouseDownRef.current = false;
      }}
      onKeyDown={handleKeyDown}
    >
      <div className={classes.stopFillContainer}>
        <div
          className={classes.stop}
          style={{ background: resolveDocumentColorToCss(stop.color) ?? stop.color ?? undefined }}
        />
      </div>
      <div className={classes.stopArrow} />
    </div>
  );
};
