/**
 * Minimal OrderedSet implementation preserving the subset of the
 * immutable.js OrderedSet contract used by consumer `customStyleFn`
 * callbacks (carried over from the Draft.js era).
 *
 * Only the methods observed in consumer code are implemented:
 * `.toArray()` and iteration. Values are unique and insertion-ordered.
 */
export class OrderedSet<T> implements Iterable<T> {
  private readonly values: T[];

  constructor(values: Iterable<T> = []) {
    const seen = new Set<T>();
    const ordered: T[] = [];
    for (const value of values) {
      if (!seen.has(value)) {
        seen.add(value);
        ordered.push(value);
      }
    }
    this.values = ordered;
  }

  static of<T>(...values: T[]): OrderedSet<T> {
    return new OrderedSet(values);
  }

  toArray(): T[] {
    return [...this.values];
  }

  [Symbol.iterator](): IterableIterator<T> {
    return this.values[Symbol.iterator]();
  }
}
